import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class OnlineStockSpanTest {

    @Test
    public void nextPriceZero_SpanIsOne() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int result = onlineStockSpan.next(0);
        assertEquals(1, result);
    }

    @Test
    public void nextPriceNegative_SpanIsOne() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int result = onlineStockSpan.next(-10);
        assertEquals(1, result);
    }

    @Test
    public void nextPricePositive_SpanIsOne() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int result = onlineStockSpan.next(10);
        assertEquals(1, result);
    }

    @Test
    public void nextPriceSameTwice_SameSpan() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        onlineStockSpan.next(5);
        onlineStockSpan.next(5);
        int result = onlineStockSpan.next(5);
        assertEquals(1, result);
    }

    @Test
    public void calculateSpansEmptyArray_ThrowsNullPointerException() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        try {
            onlineStockSpan.calculateSpans(new int[0]);
            assert false;
        } catch (NullPointerException e) {
            assertEquals(1, e.getMessage().indexOf(" prices"));
        }
    }

    @Test
    public void calculateSpansSingleElementArray_ReturnsOne() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        try {
            int[] result = onlineStockSpan.calculateSpans(new int[]{10});
            assert result != null;
            assertEquals(1, result.length);
            assertEquals(1, result[0]);
        } catch (NullPointerException e) {
            fail("Expected exception not thrown");
        }
    }

    @Test
    public void calculateSpansMultipleElements_ReturnsCorrectArray() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int[] prices = {10, 5, -3, -2, 1};
        try {
            int[] result = onlineStockSpan.calculateSpans(prices);
            assert result != null;
            assertEquals(4, result.length);
            assertEquals(1, result[0]);
            assertEquals(2, result[1]);
            assertEquals(1, result[2]);
            assertEquals(3, result[3]);
        } catch (NullPointerException e) {
            fail("Expected exception not thrown");
        }
    }

    @Test
    public void calculateSpansStackingCorrectly() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        Stack<Integer> stack = new Stack<>();
        int[] prices = {10, 5, -3, -2, 1};
        for (int price : prices) {
            int span = onlineStockSpan.next(price);
            assertEquals(span + 1, stack.size());
            if (!stack.isEmpty()) {
                assertEquals(stack.peek() + span + 1, stack.get(stack.size() - 1));
            }
        }
    }

    @Test
    public void nextPriceStackingCorrectly() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        Stack<Integer> stack = new Stack<>();
        int[] prices = {10, 5, -3, -2, 1};
        for (int price : prices) {
            onlineStockSpan.next(price);
            assertEquals(stack.size(), onlineStockSpan.calculateSpans(new int[]{prices[0]}).length);
        }
    }
}
